        _name = State(initialValue: collection?.name ?? "")
        _selectedColor = State(initialValue: collection?.colorHex ?? "007AFF")
        _selectedIcon = State(initialValue: collection?.icon ?? "folder.fill")
    }

    private let predefinedColors: [(name: String, hex: String)] = [
        ("Blue", "007AFF"),
        ("Purple", "AF52DE"),
        ("Pink", "FF2D55"),
        ("Red", "FF3B30"),
        ("Orange", "FF9500"),
        ("Yellow", "FFCC00"),
        ("Green", "34C759"),
        ("Teal", "5AC8FA"),
        ("Indigo", "5856D6"),
        ("Brown", "A2845E")
    ]

    private let predefinedIcons = [
        "folder.fill",
        "book.fill",
        "books.vertical.fill",
        "star.fill",
        "heart.fill",
        "bookmark.fill",
        "tag.fill",
        "flag.fill",
        "archivebox.fill",
        "tray.fill",
        "folder.badge.person.crop",
        "graduationcap.fill",
        "briefcase.fill",
        "house.fill",
        "lightbulb.fill"
    ]

    private var isValid: Bool {
        !name.trimmingCharacters(in: .whitespaces).isEmpty
    }

    var body: some View {
        NavigationStack {
            Form {
                Section("Name") {
                    TextField("Collection Name", text: $name)
                        .textFieldStyle(.roundedBorder)
                }

                Section("Color") {
                    LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 5), spacing: 12) {
                        ForEach(predefinedColors, id: \.hex) { colorOption in
                            Button {
                                selectedColor = colorOption.hex
                            } label: {
                                ZStack {
                                    Circle()
                                        .fill(Color(hex: colorOption.hex) ?? .blue)
                                        .frame(width: 44, height: 44)

                                    if selectedColor == colorOption.hex {
                                        Image(systemName: "checkmark")
                                            .font(.system(size: 18, weight: .bold))
                                            .foregroundStyle(.white)
                                    }
                                }
                            }
                            .buttonStyle(.plain)
                            .help(colorOption.name)
                        }
                    }
                    .padding(.vertical, 8)
                }

                Section("Icon") {
                    LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 5), spacing: 12) {
                        ForEach(predefinedIcons, id: \.self) { icon in
                            Button {
                                selectedIcon = icon
                            } label: {
                                ZStack {
                                    RoundedRectangle(cornerRadius: 8)
                                        .fill(selectedIcon == icon ? Color(hex: selectedColor)?.opacity(0.2) ?? .blue.opacity(0.2) : .clear)
                                        .overlay {
                                            RoundedRectangle(cornerRadius: 8)
                                                .stroke(selectedIcon == icon ? Color(hex: selectedColor) ?? .blue : .clear, lineWidth: 2)
                                        }
                                        .frame(width: 44, height: 44)

                                    Image(systemName: icon)
                                        .font(.system(size: 20))
                                        .foregroundStyle(selectedIcon == icon ? Color(hex: selectedColor) ?? .blue : .secondary)
                                }
                            }
                            .buttonStyle(.plain)
                        }
                    }
                    .padding(.vertical, 8)
                }

                Section("Preview") {
                    HStack(spacing: 12) {
                        ZStack {
                            Circle()
                                .fill(
                                    LinearGradient(
                                        colors: [(Color(hex: selectedColor) ?? .blue).opacity(0.3), (Color(hex: selectedColor) ?? .blue).opacity(0.2)],
                                        startPoint: .topLeading,
                                        endPoint: .bottomTrailing
                                    )
                                )
                                .frame(width: 40, height: 40)

                            Image(systemName: selectedIcon)
                                .font(.system(size: 18))
                                .foregroundStyle(Color(hex: selectedColor) ?? .blue)
                        }

                        VStack(alignment: .leading, spacing: 4) {
                            Text(name.isEmpty ? "Collection Name" : name)
                                .font(.system(size: 15, weight: .medium))
                                .foregroundStyle(name.isEmpty ? .secondary : .primary)

                            Text("0 books")
                                .font(.system(size: 12))
                                .foregroundStyle(.secondary)
                        }

                        Spacer()
                    }
                    .padding(.vertical, 8)
                }
            }
            .formStyle(.grouped)
            .navigationTitle(mode == .create ? "New Collection" : "Edit Collection")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        dismiss()
                    }
                }

                ToolbarItem(placement: .confirmationAction) {
                    Button(mode == .create ? "Create" : "Save") {
                        saveCollection()
                    }
                    .disabled(!isValid)
                }
            }
        }
        #if os(macOS)
        .frame(minWidth: 500, minHeight: 500)
        #endif
    }

    private func saveCollection() {
        let trimmedName = name.trimmingCharacters(in: .whitespaces)

        if mode == .create {
            let newCollection = BookCollection(
                name: trimmedName,
                colorHex: selectedColor,
                icon: selectedIcon
            )
            onSave(newCollection)
        } else if let collection = collection {
            let edited = BookCollection(
                id: collection.id,
                name: trimmedName,
                colorHex: selectedColor,
                icon: selectedIcon
            )
            onSave(edited)
        }

        dismiss()
    }
}

// MARK: - Color Extension

extension Color {
    init?(hex: String) {
        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0

        guard Scanner(string: hex).scanHexInt64(&int) else { return nil }

        let r, g, b: UInt64
        switch hex.count {
        case 3: // RGB (12-bit)
            (r, g, b) = ((int >> 8) * 17, (int >> 4 & 0xF) * 17, (int & 0xF) * 17)
        case 6: // RGB (24-bit)
            (r, g, b) = (int >> 16, int >> 8 & 0xFF, int & 0xFF)
        default:
            return nil
        }

        self.init(
            .sRGB,
            red: Double(r) / 255,
            green: Double(g) / 255,
            blue: Double(b) / 255
        )
    }
}

