import Foundation
import AVFoundation

/// Service for text-to-speech functionality
@Observable
final class TextToSpeechService: NSObject {
    // MARK: - Properties

    private let synthesizer = AVSpeechSynthesizer()

    /// Current reading state
    var isPlaying = false
    var isPaused = false

    /// Current utterance being spoken
    private var currentUtterance: AVSpeechUtterance?

    /// Reading speed (0.5 - 2.0, default 1.0)
    var rate: Float = AVSpeechUtteranceDefaultSpeechRate {
        didSet {
            // Clamp between valid range
            rate = min(max(rate, AVSpeechUtteranceMinimumSpeechRate), AVSpeechUtteranceMaximumSpeechRate)
        }
    }

    /// Current voice
    var selectedVoice: AVSpeechSynthesisVoice? {
        didSet {
            if isPlaying {
                // Restart with new voice
                let text = currentText
                stop()
                if let text = text {
                    speak(text: text)
                }
            }
        }
    }

    /// Current text being read (for restarting with new voice)
    private var currentText: String?

    /// Callback for when an utterance is finished
    var onFinished: (() -> Void)?

    /// Callback for progress updates (character range)
    var onProgress: ((NSRange) -> Void)?

    // MARK: - Initialization

    override init() {
        super.init()
        synthesizer.delegate = self

        // Set default voice (use enhanced quality if available)
        if let defaultVoice = AVSpeechSynthesisVoice(language: "en-US") {
            selectedVoice = defaultVoice
        }
    }

    // MARK: - Public Methods

    /// Start speaking the given text
    func speak(text: String) {
        guard !text.isEmpty else { return }

        currentText = text

        let utterance = AVSpeechUtterance(string: text)
        utterance.voice = selectedVoice
        utterance.rate = rate
        utterance.pitchMultiplier = 1.0
        utterance.volume = 1.0

        currentUtterance = utterance
        synthesizer.speak(utterance)
        isPlaying = true
        isPaused = false
    }

    /// Pause speech
    func pause() {
        guard isPlaying else { return }
        synthesizer.pauseSpeaking(at: .word)
        isPaused = true
    }

    /// Resume speech
    func resume() {
        guard isPaused else { return }
        synthesizer.continueSpeaking()
        isPaused = false
    }

    /// Stop speech
    func stop() {
        synthesizer.stopSpeaking(at: .immediate)
        isPlaying = false
        isPaused = false
        currentUtterance = nil
        currentText = nil
    }

    /// Toggle play/pause
    func togglePlayPause(text: String? = nil) {
        if isPlaying {
            if isPaused {
                resume()
            } else {
                pause()
            }
        } else if let text = text {
            speak(text: text)
        }
    }

    // MARK: - Voice Management

    /// Get available voices for a language
    static func availableVoices(for languageCode: String = "en") -> [AVSpeechSynthesisVoice] {
        let allVoices = AVSpeechSynthesisVoice.speechVoices()
        return allVoices.filter { $0.language.hasPrefix(languageCode) }
            .sorted { $0.name < $1.name }
    }

    /// Get all available voices grouped by language
    static func voicesByLanguage() -> [String: [AVSpeechSynthesisVoice]] {
        let allVoices = AVSpeechSynthesisVoice.speechVoices()
        var grouped: [String: [AVSpeechSynthesisVoice]] = [:]

        for voice in allVoices {
            let langCode = voice.language.prefix(2).description
            grouped[langCode, default: []].append(voice)
        }

        // Sort voices within each language
        for (lang, voices) in grouped {
            grouped[lang] = voices.sorted { $0.name < $1.name }
        }

        return grouped
    }

    /// Get human-readable language name
    static func languageName(for code: String) -> String {
        let locale = Locale(identifier: code)
        return locale.localizedString(forLanguageCode: code)?.capitalized ?? code
    }
}

// MARK: - AVSpeechSynthesizerDelegate

extension TextToSpeechService: AVSpeechSynthesizerDelegate {
    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didStart utterance: AVSpeechUtterance) {
        isPlaying = true
        isPaused = false
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didPause utterance: AVSpeechUtterance) {
        isPaused = true
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didContinue utterance: AVSpeechUtterance) {
        isPaused = false
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didFinish utterance: AVSpeechUtterance) {
        isPlaying = false
        isPaused = false
        currentUtterance = nil
        currentText = nil
        onFinished?()
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didCancel utterance: AVSpeechUtterance) {
        isPlaying = false
        isPaused = false
        currentUtterance = nil
        currentText = nil
    }

    func speechSynthesizer(
        _ synthesizer: AVSpeechSynthesizer,
        willSpeakRangeOfSpeechString characterRange: NSRange,
        utterance: AVSpeechUtterance
    ) {
        onProgress?(characterRange)
    }
}

import SwiftUI
import AVFoundation

/// Control panel for text-to-speech functionality
struct TTSControlPanel: View {
    @Bindable var ttsService: TextToSpeechService
    let onToggle: () -> Void

    @State private var showVoiceSettings = false
    @State private var showSpeedSlider = false

    var body: some View {
        HStack(spacing: 16) {
            // Play/Pause Button
            playPauseButton

            // Speed Control
            speedControl

            // Voice Selection
            voiceButton

            // Stop Button
            if ttsService.isPlaying || ttsService.isPaused {
                stopButton
            }
        }
        .padding(.horizontal)
        .padding(.vertical, 12)
        .background(.bar)
        .popover(isPresented: $showVoiceSettings, arrowEdge: .bottom) {
            VoiceSelectionView(ttsService: ttsService)
                .frame(width: 350, height: 400)
        }
    }

    // MARK: - Play/Pause Button

    private var playPauseButton: some View {
        Button {
            onToggle()
        } label: {
            HStack(spacing: 6) {
                Image(systemName: playPauseIcon)
                    .font(.title3)

                Text(playPauseText)
                    .font(.subheadline)
                    .fontWeight(.medium)
            }
            .frame(minWidth: 100)
        }
        .buttonStyle(.borderedProminent)
        .controlSize(.large)
    }

    private var playPauseIcon: String {
        if ttsService.isPaused {
            return "play.fill"
        } else if ttsService.isPlaying {
            return "pause.fill"
        } else {
            return "play.fill"
        }
    }

    private var playPauseText: String {
        if ttsService.isPaused {
            return "Resume"
        } else if ttsService.isPlaying {
            return "Pause"
        } else {
            return "Read Aloud"
        }
    }

    // MARK: - Speed Control

    private var speedControl: some View {
        Menu {
            ForEach(speedPresets, id: \.value) { preset in
                Button {
                    ttsService.rate = preset.value
                } label: {
                    HStack {
                        Text(preset.label)
                        if abs(ttsService.rate - preset.value) < 0.01 {
                            Image(systemName: "checkmark")
                        }
                    }
                }
            }

            Divider()

            Button {
                showSpeedSlider.toggle()
            } label: {
                HStack {
                    Text("Custom Speed...")
                    if showSpeedSlider {
                        Image(systemName: "checkmark")
                    }
                }
            }

            if showSpeedSlider {
                VStack(alignment: .leading, spacing: 8) {
                    Text("Speed: \(speedLabel)")
                        .font(.caption)
                        .foregroundStyle(.secondary)

                    Slider(value: Binding(
                        get: { Double(ttsService.rate) },
                        set: { ttsService.rate = Float($0) }
                    ), in: 0.3...2.0, step: 0.1)
                    .frame(width: 200)
                }
                .padding(8)
            }
        } label: {
            HStack(spacing: 4) {
                Image(systemName: "gauge.with.dots.needle.50percent")
                Text(speedLabel)
                    .font(.caption)
                    .monospacedDigit()
            }
        }
        .menuStyle(.borderlessButton)
    }

    private var speedLabel: String {
        String(format: "%.1fx", ttsService.rate)
    }

    private let speedPresets: [(label: String, value: Float)] = [
        ("0.5x (Slow)", 0.5),
        ("0.75x", 0.75),
        ("1.0x (Normal)", AVSpeechUtteranceDefaultSpeechRate),
        ("1.25x", 1.25),
        ("1.5x (Fast)", 1.5),
        ("2.0x (Very Fast)", 2.0)
    ]

    // MARK: - Voice Button

    private var voiceButton: some View {
        Button {
            showVoiceSettings = true
        } label: {
            HStack(spacing: 4) {
                Image(systemName: "person.wave.2")
                Text(voiceName)
                    .font(.caption)
                    .lineLimit(1)
            }
        }
    }

    private var voiceName: String {
        if let voice = ttsService.selectedVoice {
            return voice.name
        }
        return "Voice"
    }

    // MARK: - Stop Button

    private var stopButton: some View {
        Button {
            ttsService.stop()
        } label: {
            Image(systemName: "stop.fill")
        }
        .buttonStyle(.bordered)
        .tint(.red)
    }
}

