import Foundation
import AVFoundation

/// Service for text-to-speech functionality
@Observable
final class TextToSpeechService: NSObject {
    // MARK: - Properties

    private let synthesizer = AVSpeechSynthesizer()

    /// Current reading state
    var isPlaying = false
    var isPaused = false

    /// Current utterance being spoken
    private var currentUtterance: AVSpeechUtterance?

    /// Reading speed (0.5 - 2.0, default 1.0)
    var rate: Float = AVSpeechUtteranceDefaultSpeechRate {
        didSet {
            // Clamp between valid range
            rate = min(max(rate, AVSpeechUtteranceMinimumSpeechRate), AVSpeechUtteranceMaximumSpeechRate)
        }
    }

    /// Current voice
    var selectedVoice: AVSpeechSynthesisVoice? {
        didSet {
            if isPlaying {
                // Restart with new voice
                let text = currentText
                stop()
                if let text = text {
                    speak(text: text)
                }
            }
        }
    }

    /// Current text being read (for restarting with new voice)
    private var currentText: String?

    /// Callback for when an utterance is finished
    var onFinished: (() -> Void)?

    /// Callback for progress updates (character range)
    var onProgress: ((NSRange) -> Void)?

    // MARK: - Initialization

    override init() {
        super.init()
        synthesizer.delegate = self

        // Set default voice (use enhanced quality if available)
        if let defaultVoice = AVSpeechSynthesisVoice(language: "en-US") {
            selectedVoice = defaultVoice
        }
    }

    // MARK: - Public Methods

    /// Start speaking the given text
    func speak(text: String) {
        guard !text.isEmpty else { return }

        currentText = text

        let utterance = AVSpeechUtterance(string: text)
        utterance.voice = selectedVoice
        utterance.rate = rate
        utterance.pitchMultiplier = 1.0
        utterance.volume = 1.0

        currentUtterance = utterance
        synthesizer.speak(utterance)
        isPlaying = true
        isPaused = false
    }

    /// Pause speech
    func pause() {
        guard isPlaying else { return }
        synthesizer.pauseSpeaking(at: .word)
        isPaused = true
    }

    /// Resume speech
    func resume() {
        guard isPaused else { return }
        synthesizer.continueSpeaking()
        isPaused = false
    }

    /// Stop speech
    func stop() {
        synthesizer.stopSpeaking(at: .immediate)
        isPlaying = false
        isPaused = false
        currentUtterance = nil
        currentText = nil
    }

    /// Toggle play/pause
    func togglePlayPause(text: String? = nil) {
        if isPlaying {
            if isPaused {
                resume()
            } else {
                pause()
            }
        } else if let text = text {
            speak(text: text)
        }
    }

    // MARK: - Voice Management

    /// Get available voices for a language
    static func availableVoices(for languageCode: String = "en") -> [AVSpeechSynthesisVoice] {
        let allVoices = AVSpeechSynthesisVoice.speechVoices()
        return allVoices.filter { $0.language.hasPrefix(languageCode) }
            .sorted { $0.name < $1.name }
    }

    /// Get all available voices grouped by language
    static func voicesByLanguage() -> [String: [AVSpeechSynthesisVoice]] {
        let allVoices = AVSpeechSynthesisVoice.speechVoices()
        var grouped: [String: [AVSpeechSynthesisVoice]] = [:]

        for voice in allVoices {
            let langCode = voice.language.prefix(2).description
            grouped[langCode, default: []].append(voice)
        }

        // Sort voices within each language
        for (lang, voices) in grouped {
            grouped[lang] = voices.sorted { $0.name < $1.name }
        }

        return grouped
    }

    /// Get human-readable language name
    static func languageName(for code: String) -> String {
        let locale = Locale(identifier: code)
        return locale.localizedString(forLanguageCode: code)?.capitalized ?? code
    }
}

// MARK: - AVSpeechSynthesizerDelegate

extension TextToSpeechService: AVSpeechSynthesizerDelegate {
    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didStart utterance: AVSpeechUtterance) {
        isPlaying = true
        isPaused = false
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didPause utterance: AVSpeechUtterance) {
        isPaused = true
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didContinue utterance: AVSpeechUtterance) {
        isPaused = false
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didFinish utterance: AVSpeechUtterance) {
        isPlaying = false
        isPaused = false
        currentUtterance = nil
        currentText = nil
        onFinished?()
    }

    func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didCancel utterance: AVSpeechUtterance) {
        isPlaying = false
        isPaused = false
        currentUtterance = nil
        currentText = nil
    }

    func speechSynthesizer(
        _ synthesizer: AVSpeechSynthesizer,
        willSpeakRangeOfSpeechString characterRange: NSRange,
        utterance: AVSpeechUtterance
    ) {
        onProgress?(characterRange)
    }
}

